/// The value of [`use_category`].
#[inline]
pub(crate) fn use_table(cp: u32) -> u32 {
    use_table_inside(cp).unwrap_or(0)
}

#[inline]
fn use_table_inside(cp: u32) -> Option<u32> {
    let c = cp.checked_sub(0x2d)?;
    if c > 0xe0fd2 {
        return None;
    }
    let i1 = get8(&USE_TABLE_S1, c >> 10)?;
    let i2 = get8(&USE_TABLE_S2, (i1 << 5) | ((c >> 5) & 0x1f))?;
    get8(&USE_TABLE_S3, (i2 << 5) | (c & 0x1f))
}

/// HarfBuzz's `hb_use_get_category`: the category of the Universal
/// Shaping Engine, as the number of the USE machine's export.
#[inline]
pub(crate) fn use_category(cp: u32) -> u8 {
    u8::try_from(use_table(cp)).unwrap_or(0)
}
